from collections import deque
class Solution:
    def snakesAndLadders(self, board: list[list[int]]) -> int:
        n = len(board)
        target = n * n
        def position(sq):
            idx = sq - 1
            r_from_bot = idx // n
            col_off = idx % n
            row = n - 1 - r_from_bot
            col = col_off if r_from_bot % 2 == 0 else n - 1 - col_off
            return row, col
        queue = deque([1])
        visited = {1}
        moves = 0
        while queue:
            for _ in range(len(queue)):
                sq = queue.popleft()
                if sq == target:
                    return moves
                for roll in range(1, 7):
                    landing = sq + roll
                    if landing > target:
                        break
                    row, col = position(landing)
                    nxt = board[row][col] if board[row][col] != -1 else landing
                    if nxt not in visited:
                        visited.add(nxt)
                        queue.append(nxt)
            moves += 1
        return -1
